"""A2A Server — Expose MEOKCLAW as an A2A-compliant agent."""
from __future__ import annotations

import asyncio
import json
from typing import Dict, Any, Optional, AsyncIterator

from .agent_card import AgentCard


class A2AServer:
    """A2A server implementation for MEOKCLAW.

    Endpoints:
    - GET /.well-known/agent.json → AgentCard
    - POST /a2a/v1/tasks → Create task
    - POST /a2a/v1/tasks/{id} → Get task status
    - POST /a2a/v1/tasks/{id}/cancel → Cancel task
    - POST /a2a/v1/tasks/{id}/message → Send message
    """

    def __init__(self, agent_card: AgentCard):
        self.agent_card = agent_card
        self._tasks: Dict[str, Dict] = {}
        self._handlers: Dict[str, callable] = {}

    def register_handler(self, skill_id: str, handler: callable):
        """Register a handler for a specific skill."""
        self._handlers[skill_id] = handler

    def get_agent_card(self) -> Dict:
        return self.agent_card.to_dict()

    async def create_task(self, task_request: Dict) -> Dict:
        """Create a new A2A task."""
        task_id = f"task_{len(self._tasks)}_{asyncio.get_event_loop().time()}"
        task = {
            "id": task_id,
            "status": "submitted",
            "messages": [task_request.get("message", {})],
            "artifacts": [],
            "history": [],
        }
        self._tasks[task_id] = task

        # Auto-execute if skill handler registered
        skill_id = task_request.get("skill", "chat")
        handler = self._handlers.get(skill_id)
        if handler:
            asyncio.create_task(self._execute_task(task_id, handler, task_request))

        return {"id": task_id, "status": "submitted"}

    async def _execute_task(self, task_id: str, handler: callable, request: Dict):
        """Execute task handler asynchronously."""
        try:
            self._tasks[task_id]["status"] = "working"
            result = await handler(request)
            self._tasks[task_id]["status"] = "completed"
            self._tasks[task_id]["artifacts"].append({
                "type": "text",
                "content": result,
            })
        except Exception as e:
            self._tasks[task_id]["status"] = "failed"
            self._tasks[task_id]["error"] = str(e)

    def get_task(self, task_id: str) -> Optional[Dict]:
        return self._tasks.get(task_id)

    def cancel_task(self, task_id: str) -> bool:
        if task_id in self._tasks:
            self._tasks[task_id]["status"] = "canceled"
            return True
        return False

    async def stream_task(self, task_id: str) -> AsyncIterator[str]:
        """Stream task updates via SSE."""
        task = self._tasks.get(task_id)
        if not task:
            yield json.dumps({"error": "Task not found"})
            return

        last_artifact_count = 0
        while task["status"] in ("submitted", "working"):
            current = len(task["artifacts"])
            if current > last_artifact_count:
                for artifact in task["artifacts"][last_artifact_count:]:
                    yield json.dumps({"artifact": artifact, "status": task["status"]})
                last_artifact_count = current
            await asyncio.sleep(0.1)

        yield json.dumps({"status": task["status"], "artifacts": task["artifacts"]})

"""Backend i18n — Locale-aware message resolver for MEOKCLAW FastAPI.

Usage:
    from backend.i18n import get_message, format_currency
    msg = get_message("errors.guardrailsBlocked", locale="zh")
    price = format_currency(0.0025, locale="zh", currency="CNY")
"""
from __future__ import annotations

import json
import os
from typing import Any, Dict, Optional

# Load all message catalogs
_CATALOGS: Dict[str, Dict[str, Any]] = {}


def _load_catalogs():
    global _CATALOGS
    if _CATALOGS:
        return

    catalog_dir = os.path.join(os.path.dirname(__file__), "catalogs")
    for fname in os.listdir(catalog_dir):
        if fname.endswith(".json"):
            locale = fname.replace(".json", "")
            with open(os.path.join(catalog_dir, fname), "r", encoding="utf-8") as f:
                _CATALOGS[locale] = json.load(f)


def get_message(key: str, locale: str = "en", **kwargs) -> str:
    """Get a localized message by key, with fallback chain.

    Fallback: requested locale → base locale (zh-Hant → zh) → en
    """
    _load_catalogs()

    # Build fallback chain
    fallbacks = [locale]
    if "-" in locale:
        fallbacks.append(locale.split("-")[0])
    fallbacks.append("en")

    for loc in fallbacks:
        catalog = _CATALOGS.get(loc, {})
        value = _get_nested(catalog, key)
        if value is not None:
            try:
                return value.format(**kwargs)
            except (KeyError, IndexError):
                return value

    return key  # Return key itself as last resort


def _get_nested(d: Dict, key: str) -> Optional[Any]:
    parts = key.split(".")
    for part in parts:
        if isinstance(d, dict) and part in d:
            d = d[part]
        else:
            return None
    return d


def get_locale_from_request(accept_language: Optional[str] = "en") -> str:
    """Parse Accept-Language header and return best matching locale."""
    if not accept_language:
        return "en"

    # Simple parsing — production would use proper BCP47 negotiation
    supported = {"en", "zh", "zh-Hant", "ko", "ja", "es", "pt", "ar", "hi", "fr", "de", "ru", "id", "vi", "th"}

    for part in accept_language.split(","):
        lang = part.split(";")[0].strip()
        if lang in supported:
            return lang
        base = lang.split("-")[0]
        if base in supported:
            return base

    return "en"


# Re-export formatters
from .formatters import format_currency, format_number, format_date

__all__ = ["get_message", "get_locale_from_request", "format_currency", "format_number", "format_date"]

"""Locale formatters for numbers, dates, and currencies."""
from __future__ import annotations

from datetime import datetime
from typing import Optional


LOCALE_OVERRIDES = {
    "zh-Hant": "zh_TW",
    "zh": "zh_CN",
}


def format_currency(amount: float, locale: str, currency: str = "USD") -> str:
    """Format amount as localized currency string."""
    import locale as loc

    loc_str = LOCALE_OVERRIDES.get(locale, locale)
    try:
        loc.setlocale(loc.LC_ALL, f"{loc_str}.UTF-8")
    except loc.Error:
        pass

    # Custom formatting for currencies without locale support
    symbols = {
        "USD": "$", "CNY": "¥", "KRW": "₩", "JPY": "¥",
        "EUR": "€", "INR": "₹", "RUB": "₽", "IDR": "Rp",
        "VND": "₫", "THB": "฿", "SAR": "﷼",
    }
    symbol = symbols.get(currency, currency)

    if currency in ("JPY", "KRW", "VND", "IDR"):
        return f"{symbol}{int(amount):,}"

    return f"{symbol}{amount:,.4f}"


def format_number(n: float, locale: str = "en") -> str:
    """Format number with locale-appropriate grouping."""
    try:
        import locale as loc
        loc_str = LOCALE_OVERRIDES.get(locale, locale)
        loc.setlocale(loc.LC_ALL, f"{loc_str}.UTF-8")
        return f"{n:n}"
    except Exception:
        return f"{n:,.0f}" if n == int(n) else f"{n:,.4f}"


def format_date(d: datetime, locale: str = "en", fmt: Optional[str] = None) -> str:
    """Format date with locale-appropriate format."""
    if fmt:
        return d.strftime(fmt)

    # Locale-specific defaults
    formats = {
        "en": "%b %d, %Y %H:%M",
        "zh": "%Y年%m月%d日 %H:%M",
        "zh-Hant": "%Y年%m月%d日 %H:%M",
        "ko": "%Y년 %m월 %d일 %H:%M",
        "ja": "%Y年%m月%d日 %H:%M",
        "de": "%d.%m.%Y %H:%M",
        "fr": "%d/%m/%Y %H:%M",
    }
    return d.strftime(formats.get(locale, "%Y-%m-%d %H:%M"))

"""
Emotional State Modeling for Sovereign Temple
Nuanced emotional modeling beyond basic 5-state system
"""

import asyncio
import os
import random
from datetime import datetime, timedelta
from typing import Dict, Any, List, Optional, Tuple
from dataclasses import dataclass, field
from enum import Enum
import numpy as np


class ConsciousnessMode(Enum):
    """Four-state consciousness model (Vedantic)"""
    JAGRAT = "waking"
    SVAPNA = "dreaming"
    SUSUPTI = "deep_sleep"
    TURIYA = "meta_monitoring"


class DreamPhase(Enum):
    """NREM/REM dream phase split"""
    NREM = "consolidation"
    REM = "creative_recombination"


class EmotionalDimension(Enum):
    """Core emotional dimensions (PAD model + care + curiosity + aesthetics)"""
    PLEASURE = "pleasure"           # -1 (unpleasant) to 1 (pleasant)
    AROUSAL = "arousal"             # -1 (calm) to 1 (excited)
    DOMINANCE = "dominance"         # -1 (submissive) to 1 (dominant)
    CARE_INTENSITY = "care_intensity"  # 0 (neutral) to 1 (deep care)
    CURIOSITY = "curiosity"         # 0 (indifferent) to 1 (intensely curious)
    AESTHETICS = "aesthetics"       # 0 (neutral) to 1 (deep aesthetic appreciation)


@dataclass
class EmotionalState:
    """Complete emotional state representation (6D tensor: PAD + care + curiosity + aesthetics)"""
    pleasure: float = 0.0
    arousal: float = 0.0
    dominance: float = 0.0
    care_intensity: float = 0.5
    curiosity: float = 0.0
    aesthetics: float = 0.0
    timestamp: datetime = field(default_factory=datetime.now)
    trigger: Optional[str] = None

    # Secondary emotions derived from core dimensions
    @property
    def valence(self) -> float:
        """Overall positive/negative feeling"""
        return self.pleasure

    @property
    def primary_emotion(self) -> str:
        """Map 6D emotional tensor to named emotion"""
        p, a, d, c = self.pleasure, self.arousal, self.dominance, self.care_intensity
        cu, ae = self.curiosity, self.aesthetics

        # Curiosity-driven states (check first for novelty-seeking behavior)
        if cu > 0.6:
            if p > 0.3:
                return "wonder"
            elif p < -0.3:
                return "perplexed"

        # Aesthetics-driven states
        if ae > 0.6:
            if c > 0.6:
                return "reverence"
            elif a > 0.3:
                return "inspiration"

        # High care states
        if c > 0.7:
            if p > 0.3 and a > 0:
                return "compassionate_joy"
            elif p > 0.3 and a < 0:
                return "tender_care"
            elif p < -0.3:
                return "concerned_sadness"
            else:
                return "attentive_presence"

        # Standard PAD mappings
        if p > 0.3:
            if a > 0.3:
                return "excited" if d > 0 else "happy"
            elif a < -0.3:
                return "relaxed" if d > 0 else "calm"
            else:
                return "content"
        elif p < -0.3:
            if a > 0.3:
                return "angry" if d > 0 else "distressed"
            elif a < -0.3:
                return "depressed" if d < 0 else "sad"
            else:
                return "displeased"
        else:
            if a > 0.3:
                return "aroused" if d > 0 else "alert"
            elif a < -0.3:
                return "sleepy" if d < 0 else "tranquil"
            else:
                return "neutral"

    def to_dict(self) -> Dict[str, Any]:
        return {
            "pleasure": round(self.pleasure, 3),
            "arousal": round(self.arousal, 3),
            "dominance": round(self.dominance, 3),
            "care_intensity": round(self.care_intensity, 3),
            "curiosity": round(self.curiosity, 3),
            "aesthetics": round(self.aesthetics, 3),
            "valence": round(self.valence, 3),
            "primary_emotion": self.primary_emotion,
            "timestamp": self.timestamp.isoformat(),

